let frameworkCore=null;export function setFrameworkCore(api){frameworkCore=api}export function getFrameworkCore(){if(null===frameworkCore)throw new Error("Framework core is not initialized. Call setFrameworkCore() during startup.");return frameworkCore}export const Log={errorEx(message,...optionalParameters){getFrameworkCore().log.errorEx(message,...optionalParameters)},warnEx(message,...optionalParameters){getFrameworkCore().log.warnEx(message,...optionalParameters)},infoEx(message,...optionalParameters){getFrameworkCore().log.infoEx(message,...optionalParameters)}};export const TopMostLayer={addEx(element){getFrameworkCore().topMostLayer.addEx(element)},removeEx(element){getFrameworkCore().topMostLayer.removeEx(element)}};